115. //==================================================================================================
116. // Abstract projections of the opaque address / permission types
117. //==================================================================================================
118. 
119. /// Projection of an address-like value to its raw byte address as a `nat`.
120. pub trait AddrNat {
121.     spec fn addr_nat(&self) -> nat;
122. }
123. 
124. impl AddrNat for VirtualAddress {
125.     uninterp spec fn addr_nat(&self) -> nat;
126. }
127. 
128. impl AddrNat for PageAligned<VirtualAddress> {
129.     uninterp spec fn addr_nat(&self) -> nat;
130. }
131. 
132. impl AddrNat for PhysicalAddress {
133.     uninterp spec fn addr_nat(&self) -> nat;
134. }
135. 
136. impl AddrNat for FrameAddress {
137.     uninterp spec fn addr_nat(&self) -> nat;
138. }
139. 
140. impl AddrNat for UserFrame {
141.     uninterp spec fn addr_nat(&self) -> nat;
142. }
143. 
144. impl AddrNat for KernelPage {
145.     uninterp spec fn addr_nat(&self) -> nat;
146. }
147. 
148. impl AddrNat for PageDirectory<PageDirectoryStorage> {
149.     uninterp spec fn addr_nat(&self) -> nat;
150. }
151. 
152. /// Projection of the concrete permission encoding to the abstract triple.
153. pub trait PermView {
154.     spec fn perms_view(&self) -> PagePerms;
155. }
156. 
157. impl PermView for AccessPermission {
158.     uninterp spec fn perms_view(&self) -> PagePerms;
159. }
160. 
161. //==================================================================================================
162. // Architectural constants (mirror `sys::config` / `arch::mem` layout values)
163. //==================================================================================================
164. 
165. /// Page size in bytes (`arch::mem::PAGE_SIZE`).
166. pub open spec fn page_size() -> nat {
167.     4096
168. }
169. 
170. /// Abstract permission triple of the hardcoded `AccessPermission::RDWR` constant
171. /// (read + write, no execute) used by `map_kpage` when installing kernel pages.
172. pub open spec fn rdwr_perms() -> PagePerms {
173.     PagePerms { read: true, write: true, execute: false }
174. }
175. 
176. /// First user-space byte address (`config::memory_layout::USER_BASE_RAW`).
177. pub open spec fn user_base() -> nat {
178.     0x4000_0000
179. }
180. 
181. /// One-past-last user-space byte address (`config::memory_layout::USER_END_RAW`).
182. pub open spec fn user_end() -> nat {
183.     0xf000_0000
184. }
185. 
186. /// Size of valid guest physical memory (`config::kernel::MEMORY_SIZE`).
187. ///
188. /// Modeled as a literal (mirroring `page_size`/`user_base`/`user_end` above)
189. /// because the generated `config::kernel::MEMORY_SIZE` const is not reachable
190. /// from spec context. Kept in sync with the build-time configuration
191. /// (`src/libs/config/build.rs`, currently 128 MiB).
192. pub open spec fn phys_mem_size() -> nat {
193.     0x800_0000
194. }
195. 
196. //==================================================================================================
197. // Address-partition helpers (pure, total, instance-independent)
198. //==================================================================================================
199. 
200. pub open spec fn is_page_aligned(a: nat) -> bool {
201.     a % page_size() == 0
202. }
203. 
204. /// Page-aligned base of the page containing `a`.
205. pub open spec fn page_base(a: nat) -> nat {
206.     (a - (a % page_size())) as nat
207. }
208. 
209. /// Intra-page offset of `a`.
210. pub open spec fn page_offset(a: nat) -> nat {
211.     a % page_size()
212. }
213. 
214. /// Whether `a` lies in user space.
215. pub open spec fn spec_is_user_addr(a: nat) -> bool {
216.     user_base() <= a < user_end()
217. }
218. 
219. /// Whether `a` lies in kernel space (the total complement of user space).
220. pub open spec fn spec_is_kernel_addr(a: nat) -> bool {
221.     !spec_is_user_addr(a)
222. }
223. 
224. /// Whether `[start, start+size)` lies entirely in user space.
225. pub open spec fn spec_is_user_region(start: nat, size: nat) -> bool {
226.     &&& size > 0
227.     &&& user_base() <= start
228.     &&& start + size <= user_end()
229. }
230. 
231. /// Whether `[start, start+size)` lies entirely in kernel space (below the user
232. /// window). Matches the kernel half of the address partition.
233. pub open spec fn spec_is_kernel_region(start: nat, size: nat) -> bool {
234.     &&& size > 0
235.     &&& start + size <= user_base()
236. }
237. 
238. /// Whether `[start, start+size)` lies entirely within valid physical memory.
239. /// (`hal::platform::is_valid_physical_region`: rejects empty ranges.)
240. pub open spec fn spec_is_physical_region(start: nat, size: nat) -> bool {
241.     &&& size > 0
242.     &&& start + size <= phys_mem_size()
243. }
244. 
245. //==================================================================================================
246. // PagePerms — abstract access permissions
247. //==================================================================================================
248. 
249. /// Abstract access permissions of a mapped page.
250. pub struct PagePerms {
251.     pub read: bool,
252.     pub write: bool,
253.     pub execute: bool,
254. }
255. 
256. //==================================================================================================
257. // UserPageView / KernelPageView — single-mapping abstractions
258. //==================================================================================================
259. 
260. /// Abstract state of a single user-space mapping.
261. pub struct UserPageView {
262.     /// Physical base address of the backing user frame.
263.     pub frame: nat,
264.     /// Access permissions currently in effect for the page.
265.     pub perms: PagePerms,
266.     /// Whether the page is marked copy-on-write.
267.     pub cow: bool,
268. }
269. 
270. /// Abstract state of a single kernel-space mapping.
271. pub struct KernelPageView {
272.     /// Physical base address of the backing kernel page/frame.
273.     pub frame: nat,
274.     /// Access permissions currently in effect for the page.
275.     pub perms: PagePerms,
276. }
277. 
278. //==================================================================================================
279. // VmemView — abstract state of an entire address space
280. //==================================================================================================
281. 
282. /// Abstract view of a virtual memory space.
283. pub struct VmemView {
284.     /// User half: page-aligned user vaddr -> mapping.
285.     pub user: Map<nat, UserPageView>,
286.     /// Kernel half: page-aligned kernel vaddr -> mapping.
287.     pub kernel: Map<nat, KernelPageView>,
288.     /// Physical base address of the page directory (the value loaded into CR3).
289.     pub pgdir: nat,
290. }
291. 
292. impl VmemView {
293.     //==============================================================================================
294.     // Well-formedness invariant
295.     //==============================================================================================
296. 
297.     pub open spec fn inv(self) -> bool {
298.         // User keys are page-aligned user addresses.
299.         &&& forall|v: nat| #[trigger] self.user.contains_key(v)
300.                 ==> spec_is_user_addr(v) && is_page_aligned(v)
301.         // Kernel keys are page-aligned kernel addresses.
302.         &&& forall|v: nat| #[trigger] self.kernel.contains_key(v)
303.                 ==> spec_is_kernel_addr(v) && is_page_aligned(v)
304.         // User frames are valid, page-aligned, and CoW implies read-only.
305.         &&& forall|v: nat| #[trigger] self.user.contains_key(v) ==> {
306.                 &&& is_page_aligned(self.user[v].frame)
307.                 &&& spec_is_physical_region(self.user[v].frame, page_size())
308.                 &&& (self.user[v].cow ==> !self.user[v].perms.write)
309.             }
310.         // Kernel frames are page-aligned. They lie within guest physical memory, *unless*
311.         // they are identity-mapped MMIO frames (frame == vaddr), which legitimately fall
312.         // outside RAM (see `kctrl`'s MMIO mapping-creation branch / SB-1). This relaxation
313.         // is faithful to the code and does not weaken any caller-relied guarantee: callers
314.         // never assume kernel frames lie in RAM.
315.         &&& forall|v: nat| #[trigger] self.kernel.contains_key(v) ==> {
316.                 &&& is_page_aligned(self.kernel[v].frame)
317.                 &&& (spec_is_physical_region(self.kernel[v].frame, page_size())
318.                         || self.kernel[v].frame == v)
319.             }
320.         // The page directory has a valid, page-aligned physical base.
321.         &&& is_page_aligned(self.pgdir)
322.         &&& spec_is_physical_region(self.pgdir, page_size())
323.     }
324. 
325.     //==============================================================================================
326.     // Observers
327.     //==============================================================================================
328. 
329.     /// Whether user virtual page `v` is mapped.
330.     pub open spec fn user_mapped(self, v: nat) -> bool {
331.         self.user.contains_key(v)
332.     }
333. 
334.     /// Whether kernel virtual page `v` is mapped.
335.     pub open spec fn kernel_mapped(self, v: nat) -> bool {
336.         self.kernel.contains_key(v)
337.     }
338. 
339.     /// Every CoW user page overlapping `[start, start+size)` is privatized.
340.     pub open spec fn region_cow_resolved(self, start: nat, size: nat) -> bool {
341.         forall|v: nat| #[trigger] self.user.contains_key(v)
342.             && page_base(start) <= v < start + size
343.             ==> !self.user[v].cow
344.     }
345. 
346.     //==============================================================================================
347.     // State transitions (mutators preserve unchanged fields via `..self`)
348.     //==============================================================================================
349. 
350.     pub open spec fn spec_map(self, v: nat, frame: nat, perms: PagePerms) -> VmemView {
351.         VmemView { user: self.user.insert(v, UserPageView { frame, perms, cow: false }), ..self }
352.     }
353. 
354.     pub open spec fn spec_unmap(self, v: nat) -> VmemView {
355.         VmemView { user: self.user.remove(v), ..self }
356.     }
357. 
358.     pub open spec fn spec_map_kpage(self, v: nat, frame: nat, perms: PagePerms) -> VmemView {
359.         VmemView { kernel: self.kernel.insert(v, KernelPageView { frame, perms }), ..self }
360.     }
361. 
362.     pub open spec fn spec_mark_cow(self, v: nat) -> VmemView {
363.         VmemView {
364.             user: self.user.insert(
365.                 v,
366.                 UserPageView {
367.                     perms: PagePerms { write: false, ..self.user[v].perms },
368.                     cow: true,
369.                     ..self.user[v]
370.                 },
371.             ),
372.             ..self
373.         }
374.     }
375. 
376.     pub open spec fn spec_unmark_cow(self, v: nat) -> VmemView {
377.         VmemView {
378.             user: self.user.insert(
379.                 v,
380.                 UserPageView {
381.                     perms: PagePerms { write: true, ..self.user[v].perms },
382.                     cow: false,
383.                     ..self.user[v]
384.                 },
385.             ),
386.             ..self
387.         }
388.     }
389. 
390.     /// `new_frame` is the freshly allocated private frame supplied existentially
391.     /// by the caller's ensures clause.
392.     pub open spec fn spec_resolve_cow(self, v: nat, new_frame: nat) -> VmemView {
393.         VmemView {
394.             user: self.user.insert(
395.                 v,
396.                 UserPageView {
397.                     frame: new_frame,
398.                     perms: PagePerms { write: true, ..self.user[v].perms },
399.                     cow: false,
400.                 },
401.             ),
402.             ..self
403.         }
404.     }
405. 
406.     pub open spec fn spec_uctrl(self, v: nat, perms: PagePerms) -> VmemView {
407.         VmemView {
408.             user: self.user.insert(v, UserPageView { perms, ..self.user[v] }),
409.             ..self
410.         }
411.     }
412. 
413.     pub open spec fn spec_kctrl(self, v: nat, perms: PagePerms) -> VmemView {
414.         VmemView {
415.             kernel: self.kernel.insert(v, KernelPageView { perms, ..self.kernel[v] }),
416.             ..self
417.         }
418.     }
419. 
420.     /// `kctrl` on an *absent* kernel page: the implementation creates a fresh
421.     /// identity-mapped entry (`frame == v`) carrying `perms` (the MMIO
422.     /// mapping-creation branch). Modeled separately from `spec_kctrl`, which
423.     /// assumes the key is already present. See SB-1.
424.     pub open spec fn spec_kctrl_create(self, v: nat, perms: PagePerms) -> VmemView {
425.         VmemView {
426.             kernel: self.kernel.insert(v, KernelPageView { frame: v, perms }),
427.             ..self
428.         }
429.     }
430. }
431. 
432. //==================================================================================================
433. // Vmem — View and invariant
434. //==================================================================================================
435. 
436. impl View for Vmem {
437.     type V = VmemView;
438. 
439.     closed spec fn view(&self) -> VmemView {
440.         self.vmem_view@
441.     }
442. }
443. 
444. impl Vmem {
445.     /// Top-level invariant: the abstract view is well-formed.
446.     pub open spec fn inv(&self) -> bool {
447.         &&& self@.inv()
448.         &&& self.internal_inv()
449.     }
450. 
451.     /// Internal consistency between the concrete page-table representation and
452.     /// the abstract view. Refined during the proving phase.
453.     pub open spec fn internal_inv(&self) -> bool {
454.         true
455.     }
456. }
457. 
458. } // verus!
459.

